namespace sv_1fd62ac59dea4309a3aadb3837c10010.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@page "/settings"
@using sv_1fd62ac59dea4309a3aadb3837c10010.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    <nav class="settings-sidebar">
        <ul>
            @foreach (var section in _sections)
            {
                <li class="@(ActiveSection == section.Key ? "active" : "")" @onclick="() => ActiveSection = section.Key">
                    <span class="nav-icon">@section.Icon</span>
                    <span>@section.Label</span>
                </li>
            }
        </ul>
    </nav>

    <main class="settings-content">
        @if (_loading)
        {
            <div class="loading-spinner">Loading...</div>
        }
        else
        {
            @switch (ActiveSection)
            {
                case "profile":
                    @RenderProfileSection()
                    break;
                case "notifications":
                    @RenderNotificationsSection()
                    break;
                case "security":
                    @RenderSecuritySection()
                    break;
                case "appearance":
                    @RenderAppearanceSection()
                    break;
            }
        }

        @if (!string.IsNullOrEmpty(_toastMessage))
        {
            <div class="toast @(_toastType)">@_toastMessage</div>
        }
    </main>
</div>

@if (_showRevokeConfirmation)
{
    <div class="modal-overlay" @onclick="CancelRevoke">
        <div class="modal-dialog" @onclick:stopPropagation="true">
            <h3>Revoke Session</h3>
            <p>Are you sure you want to revoke this session? The device will be logged out immediately.</p>
            <div class="modal-actions">
                <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                <button class="btn btn-danger" @onclick="ConfirmRevoke">Revoke</button>
            </div>
        </div>
    </div>
}

@code {
    private string ActiveSection { get; set; } = "profile";
    private bool _loading = true;
    private string? _toastMessage;
    private string _toastType = "success";

    private record SectionInfo(string Key, string Label, string Icon);
    private readonly SectionInfo[] _sections =
    [
        new("profile", "Profile", "👤"),
        new("notifications", "Notifications", "🔔"),
        new("security", "Security", "🔒"),
        new("appearance", "Appearance", "🎨")
    ];

    // Profile state
    private UserProfile? _savedProfile;
    private string _profileDisplayName = "";
    private string _profileEmail = "";
    private string _profileBio = "";
    private string _profileAvatarUrl = "";

    // Notifications state
    private NotificationPrefs? _notificationPrefs;
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private List<string> _mutedChannels = new();
    private readonly string[] _availableChannels = ["general", "announcements", "updates", "marketing", "support"];

    // Security state
    private SecuritySettings? _securitySettings;
    private bool _changePasswordExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _showRevokeConfirmation;
    private string? _sessionToRevoke;

    // Appearance state
    private AppearanceSettings? _appearanceSettings;
    private string _theme = "System";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private readonly string[] _languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese"];

    protected override async Task OnInitializedAsync()
    {
        await LoadAllDataAsync();
        _loading = false;
    }

    private async Task LoadAllDataAsync()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

        _savedProfile = await profileTask;
        LoadProfileFromSaved();

        _notificationPrefs = await notifTask;
        _emailNotifications = _notificationPrefs.EmailNotifications;
        _pushNotifications = _notificationPrefs.PushNotifications;
        _weeklyDigest = _notificationPrefs.WeeklyDigest;
        _mutedChannels = new List<string>(_notificationPrefs.MutedChannels);

        _securitySettings = await securityTask;

        _appearanceSettings = await appearanceTask;
        _theme = _appearanceSettings.Theme;
        _fontSize = _appearanceSettings.FontSize;
        _language = _appearanceSettings.Language;
        _compactMode = _appearanceSettings.CompactMode;
    }

    private void LoadProfileFromSaved()
    {
        if (_savedProfile is null) return;
        _profileDisplayName = _savedProfile.DisplayName;
        _profileEmail = _savedProfile.Email;
        _profileBio = _savedProfile.Bio;
        _profileAvatarUrl = _savedProfile.AvatarUrl;
    }

    // Profile actions
    private async Task SaveProfile()
    {
        var profile = new UserProfile(_profileDisplayName, _profileEmail, _profileAvatarUrl, _profileBio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        ShowToast("Profile saved successfully!", "success");
    }

    private void DiscardProfileChanges()
    {
        LoadProfileFromSaved();
        ShowToast("Changes discarded.", "info");
    }

    // Notifications actions
    private void ToggleMuteChannel(string channel)
    {
        if (_mutedChannels.Contains(channel))
            _mutedChannels.Remove(channel);
        else
            _mutedChannels.Add(channel);
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, new List<string>(_mutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _notificationPrefs = prefs;
        ShowToast("Notification preferences saved!", "success");
    }

    // Security actions
    private async Task ChangePassword()
    {
        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            ShowToast("Please fill in all password fields.", "error");
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            ShowToast("New passwords do not match.", "error");
            return;
        }
        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _changePasswordExpanded = false;
        ShowToast("Password updated successfully!", "success");
    }

    private void RequestRevokeSession(string sessionId)
    {
        _sessionToRevoke = sessionId;
        _showRevokeConfirmation = true;
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
        _showRevokeConfirmation = false;
    }

    private async Task ConfirmRevoke()
    {
        if (_sessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke);
            _securitySettings = await SettingsService.GetSecuritySettingsAsync();
            ShowToast("Session revoked.", "success");
        }
        _sessionToRevoke = null;
        _showRevokeConfirmation = false;
    }

    // Appearance actions
    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _appearanceSettings = settings;
        ShowToast("Appearance settings saved!", "success");
    }

    // Toast helper
    private void ShowToast(string message, string type)
    {
        _toastMessage = message;
        _toastType = type;
        _ = DismissToastAsync();
    }

    private async Task DismissToastAsync()
    {
        await Task.Delay(3000);
        _toastMessage = null;
        await InvokeAsync(StateHasChanged);
    }

    // Render fragments
    private RenderFragment RenderProfileSection() => __builder =>
    {
        <h2>Profile Settings</h2>
        <div class="settings-section">
            <div class="avatar-preview">
                @if (!string.IsNullOrWhiteSpace(_profileAvatarUrl))
                {
                    <img src="@_profileAvatarUrl" alt="Avatar" class="avatar-img" />
                }
                else
                {
                    <div class="avatar-placeholder">No Avatar</div>
                }
                <span class="avatar-url-display">@_profileAvatarUrl</span>
            </div>

            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" @bind="_profileDisplayName" class="form-control" />
            </div>

            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" @bind="_profileEmail" class="form-control" />
            </div>

            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" @bind="_profileBio" class="form-control" rows="4"></textarea>
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
            </div>
        </div>
    };

    private RenderFragment RenderNotificationsSection() => __builder =>
    {
        <h2>Notification Preferences</h2>
        <div class="settings-section">
            <div class="toggle-group">
                <label class="toggle-label">
                    <span>Email Notifications</span>
                    <label class="switch">
                        <input type="checkbox" @bind="_emailNotifications" />
                        <span class="slider"></span>
                    </label>
                </label>

                <label class="toggle-label">
                    <span>Push Notifications</span>
                    <label class="switch">
                        <input type="checkbox" @bind="_pushNotifications" />
                        <span class="slider"></span>
                    </label>
                </label>

                <label class="toggle-label">
                    <span>Weekly Digest</span>
                    <label class="switch">
                        <input type="checkbox" @bind="_weeklyDigest" />
                        <span class="slider"></span>
                    </label>
                </label>
            </div>

            <h3>Muted Channels</h3>
            <div class="channel-list">
                @foreach (var channel in _availableChannels)
                {
                    <label class="channel-item">
                        <input type="checkbox" checked="@_mutedChannels.Contains(channel)"
                               @onchange="() => ToggleMuteChannel(channel)" />
                        <span>#@channel</span>
                    </label>
                }
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
            </div>
        </div>
    };

    private RenderFragment RenderSecuritySection() => __builder =>
    {
        <h2>Security Settings</h2>
        <div class="settings-section">
            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => _changePasswordExpanded = !_changePasswordExpanded">
                    <span>Change Password</span>
                    <span class="expand-icon">@(_changePasswordExpanded ? "▼" : "▶")</span>
                </button>
                @if (_changePasswordExpanded)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label for="currentPw">Current Password</label>
                            <input id="currentPw" type="password" @bind="_currentPassword" class="form-control" />
                        </div>
                        <div class="form-group">
                            <label for="newPw">New Password</label>
                            <input id="newPw" type="password" @bind="_newPassword" class="form-control" />
                        </div>
                        <div class="form-group">
                            <label for="confirmPw">Confirm Password</label>
                            <input id="confirmPw" type="password" @bind="_confirmPassword" class="form-control" />
                        </div>
                        <button class="btn btn-primary" @onclick="ChangePassword">Update Password</button>
                    </div>
                }
            </div>

            <div class="toggle-label" style="margin-top:1.5rem;">
                <span>
                    Two-Factor Authentication
                    @if (_securitySettings?.TwoFactorEnabled == true)
                    {
                        <span class="status-badge enabled">Enabled</span>
                    }
                    else
                    {
                        <span class="status-badge disabled">Disabled</span>
                    }
                </span>
            </div>

            @if (_securitySettings?.LastPasswordChange is not null)
            {
                <p class="meta-info">Last password change: @_securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
            }

            <h3>Active Sessions</h3>
            @if (_securitySettings?.Sessions.Count > 0)
            {
                <table class="sessions-table">
                    <thead>
                        <tr>
                            <th>Device</th>
